+void* read_bpf_iter(void* arg) {
+    int fd = *(int*)arg;
+    char buf[4096];
+    ssize_t bytes_read;
+
+    while ((bytes_read = read(fd, buf, sizeof(buf))) > 0) {
+        ssize_t written_bytes = write(STDOUT_FILENO, buf, bytes_read);
+        ws_log(LOG_DOMAIN_CAPCHILD, LOG_LEVEL_ERROR,
+                          "bytes written: %ld", written_bytes);
+    }
+
+    close(fd);
+    return NULL;
+}
